import{_ as a,o as s,c as o,a2 as n}from"./chunks/framework.CuUVYbLV.js";const g=JSON.parse('{"title":"06 加上审批门与有界循环","description":"教程第 06 章：给流水线加人工审批门，并用 max_traversals 给评审循环设硬上限。","frontmatter":{"title":"06 加上审批门与有界循环","description":"教程第 06 章：给流水线加人工审批门，并用 max_traversals 给评审循环设硬上限。"},"headers":[],"relativePath":"02-Guide/tutorial/06-approval-and-loop.md","filePath":"02-Guide/tutorial/06-approval-and-loop.md"}'),p={name:"02-Guide/tutorial/06-approval-and-loop.md"};function t(d,e,i,l,c,r){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="_06-加上审批门与有界循环-approval-gate-and-bounded-loop" tabindex="-1">06 加上审批门与有界循环（Approval Gate and Bounded Loop） <a class="header-anchor" href="#_06-加上审批门与有界循环-approval-gate-and-bounded-loop" aria-label="Permalink to &quot;06 加上审批门与有界循环（Approval Gate and Bounded Loop）&quot;">​</a></h1><p>本章给 05 章的流水线补上两件让它「敢用」的东西：关键节点停下来等人点头，以及评审打回重做的循环有硬性次数上限。</p><blockquote><p>前置：<a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">教程 05 用图引擎编排团队</a>｜相关：<a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a>、<a href="/rolebox-docs/04-Advanced/workflow-patterns.html">工作流模式</a>｜引擎内部：<a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a></p></blockquote><h2 id="起点-05-章那条流水线" tabindex="-1">起点：05 章那条流水线 <a class="header-anchor" href="#起点-05-章那条流水线" aria-label="Permalink to &quot;起点：05 章那条流水线&quot;">​</a></h2><p>05 章建了一条三节点流水线：<code>coder</code> 实现 → <code>reviewer</code> 评审 → <code>finalize</code> 定稿，两条 <code>always</code> 边把它们串起来，<code>graph_run</code> 之后引擎自动推进，直到注入 <code>[GRAPH COMPLETE]</code>。</p><p>这条流水线跑得太顺了：定稿直接落地，没有人过目；评审不通过时也没有回头路。本章分两步补齐——先加<strong>审批门（approval gate，节点声明 <code>needs_approval: true</code> 后，代理发出 <code>need_approval</code> 信号时引擎把该节点置为 <code>blocked</code>、暂停其下游分支的机制）</strong>，再给回头路加<strong>循环组（loop group，用 <code>graph_add_loop</code> 声明的、由 <code>revise_needed</code> 回边驱动重跑的节点集合）</strong>。</p><h2 id="第-1-步-建一张带审批门的图" tabindex="-1">第 1 步：建一张带审批门的图 <a class="header-anchor" href="#第-1-步-建一张带审批门的图" aria-label="Permalink to &quot;第 1 步：建一张带审批门的图&quot;">​</a></h2><p>节点一旦声明就不能再改，所以本章新建一张同形状的图，只在 <code>finalize</code> 上加门。在会话里对角色说：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用图工具再建一张流水线，叫 review-pipeline-gated：</span></span>
<span class="line"><span>coder 实现 → reviewer 评审 → finalize 定稿。</span></span>
<span class="line"><span>finalize 要人工审批：它的提示词里写明——产出定稿后先调用 signal 工具，</span></span>
<span class="line"><span>type 用 need_approval，把定稿摘要放进 payload，等我批准再输出最终稿。</span></span>
<span class="line"><span>三个节点的 agent 分别用 code-reviewer--coder、code-reviewer--reviewer、</span></span>
<span class="line"><span>code-reviewer--doc-writer，两条边都用 always。</span></span></code></pre></div><p>角色会在同一回合里依次调用这些工具（这里省略了各节点的 prompt 正文）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_create({ name: &quot;review-pipeline-gated&quot; })</span></span>
<span class="line"><span>graph_add_node({ graph_id: &quot;review-pipeline-gated&quot;, id: &quot;coder&quot;,</span></span>
<span class="line"><span>                 agent: &quot;code-reviewer--coder&quot;, prompt: &quot;实现改动并输出补丁&quot; })</span></span>
<span class="line"><span>graph_add_node({ graph_id: &quot;review-pipeline-gated&quot;, id: &quot;reviewer&quot;,</span></span>
<span class="line"><span>                 agent: &quot;code-reviewer--reviewer&quot;, prompt: &quot;评审上游产物&quot; })</span></span>
<span class="line"><span>graph_add_node({ graph_id: &quot;review-pipeline-gated&quot;, id: &quot;finalize&quot;,</span></span>
<span class="line"><span>                 agent: &quot;code-reviewer--doc-writer&quot;, needs_approval: true,</span></span>
<span class="line"><span>                 prompt: &quot;产出定稿说明后调用 signal 工具发 need_approval，等待批准&quot; })</span></span>
<span class="line"><span>graph_add_edge({ graph_id: &quot;review-pipeline-gated&quot;, from: &quot;coder&quot;, to: &quot;reviewer&quot; })</span></span>
<span class="line"><span>graph_add_edge({ graph_id: &quot;review-pipeline-gated&quot;, from: &quot;reviewer&quot;, to: &quot;finalize&quot; })</span></span>
<span class="line"><span>graph_run({ graph_id: &quot;review-pipeline-gated&quot; })</span></span></code></pre></div><p><code>graph_run</code> 是非阻塞的，派发就绪节点后立刻返回：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，active / pending 的具体成员取决于调用时刻）：</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;graph_id&quot;: &quot;review-pipeline-gated&quot;,</span></span>
<span class="line"><span>  &quot;phase&quot;: &quot;executing&quot;,</span></span>
<span class="line"><span>  &quot;active_nodes&quot;: [&quot;coder&quot;],</span></span>
<span class="line"><span>  &quot;pending_nodes&quot;: [&quot;reviewer&quot;, &quot;finalize&quot;]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong><code>needs_approval: true</code> 只是「允许暂停」，不是「自动暂停」。</strong> 引擎是在节点发出 <code>need_approval</code> 信号时才把它置为 <code>blocked</code> 的；反过来，没声明 <code>needs_approval</code> 的节点即使发了这个信号也不会挡住图。所以门上那个节点的提示词必须指示代理去发信号——上面 <code>finalize</code> 的 prompt 里那句话，就是本章最关键的一行配置。</p><h2 id="第-2-步-结束回合-等-graph-blocked" tabindex="-1">第 2 步：结束回合，等 [GRAPH BLOCKED] <a class="header-anchor" href="#第-2-步-结束回合-等-graph-blocked" aria-label="Permalink to &quot;第 2 步：结束回合，等 [GRAPH BLOCKED]&quot;">​</a></h2><p>调用完 <code>graph_run</code> 就结束当前回合：<code>coder</code>、<code>reviewer</code> 依次完成，<code>finalize</code> 发出 <code>need_approval</code>，引擎把它置为 <code>blocked</code> 并冻结它的下游分支。当图不再有可推进的节点、却又有人在等审批时，引擎注入一条系统提醒：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;system-reminder&gt;</span></span>
<span class="line"><span>[GRAPH BLOCKED]</span></span>
<span class="line"><span>graph: review-pipeline-gated</span></span>
<span class="line"><span>phase: executing</span></span>
<span class="line"><span>nodes: completed=2 blocked=1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ Graph quiescent-blocked — nodes await approval.</span></span>
<span class="line"><span>→ Inspect blocked nodes: graph_status(graph_id=&quot;review-pipeline-gated&quot;, status=&quot;blocked&quot;, include_output=true)</span></span>
<span class="line"><span>→ Approve: graph_approve(graph_id=&quot;review-pipeline-gated&quot;, node_id=&quot;&lt;blocked_node_id&gt;&quot;, action=&quot;approve&quot;)</span></span>
<span class="line"><span>→ Reject: graph_approve(graph_id=&quot;review-pipeline-gated&quot;, node_id=&quot;&lt;blocked_node_id&gt;&quot;, action=&quot;reject&quot;) with reason</span></span>
<span class="line"><span>→ Read all results: graph_status(graph_id=&quot;review-pipeline-gated&quot;, include_output=true)</span></span>
<span class="line"><span>&lt;/system-reminder&gt;</span></span></code></pre></div><p>注意 <code>phase</code> 仍然是 <code>executing</code>：图的生命周期阶段只有 <code>idle</code> / <code>executing</code> / <code>complete</code> 三个值，审批门不改变阶段，图只是停在原地等人。停住的也不是整张图——<code>finalize</code> 的下游分支被冻结，已经完成的节点照常收尾。</p><h2 id="第-3-步-列出待批节点" tabindex="-1">第 3 步：列出待批节点 <a class="header-anchor" href="#第-3-步-列出待批节点" aria-label="Permalink to &quot;第 3 步：列出待批节点&quot;">​</a></h2><p>下一回合，用 <code>pending_approvals: true</code> 专门查「等人类点头」的节点：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_status({ graph_id: &quot;review-pipeline-gated&quot;, pending_approvals: true })</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出，时间随实际运行变化）：</span></span>
<span class="line"><span>Pending approvals (1)  [scope: session]</span></span>
<span class="line"><span>  finalize  (graph: review-pipeline-gated)</span></span>
<span class="line"><span>    agent: code-reviewer--doc-writer</span></span>
<span class="line"><span>    blocked-since: 2026-09-17T08:21:04.512Z</span></span>
<span class="line"><span>    approve: graph_approve(graph_id=&quot;review-pipeline-gated&quot;, node_id=&quot;finalize&quot;, action=&quot;approve&quot;)</span></span></code></pre></div><p>这是一个跨图视图：不传 <code>graph_id</code> 时会扫描当前会话里所有图，每一行都自带一条可直接复制的 <code>graph_approve</code> 调用。<code>graph_status(..., status: &quot;blocked&quot;)</code> 是另一种看法——按节点状态过滤；<code>pending_approvals</code> 回答的则是「现在有什么在等我决策」。两者都只列真实记录的节点，没有待批项时会明确说 <code>no pending approvals</code>。</p><h2 id="第-4-步-放行或打回" tabindex="-1">第 4 步：放行或打回 <a class="header-anchor" href="#第-4-步-放行或打回" aria-label="Permalink to &quot;第 4 步：放行或打回&quot;">​</a></h2><p>批准：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_approve({ graph_id: &quot;review-pipeline-gated&quot;, node_id: &quot;finalize&quot;, action: &quot;approve&quot; })</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出）：</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;graph_id&quot;: &quot;review-pipeline-gated&quot;,</span></span>
<span class="line"><span>  &quot;node_id&quot;: &quot;finalize&quot;,</span></span>
<span class="line"><span>  &quot;action&quot;: &quot;approve&quot;,</span></span>
<span class="line"><span>  &quot;node_status&quot;: &quot;completed&quot;,</span></span>
<span class="line"><span>  &quot;phase&quot;: &quot;complete&quot;,</span></span>
<span class="line"><span>  &quot;applied&quot;: true</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>approve</code> 把节点从 <code>blocked</code> 推到 <code>completed</code>，再沿它的 <code>answer</code> 数据流放行下游。本例的 <code>finalize</code> 是最后一个节点，所以图随即进入 <code>complete</code>，引擎注入 <code>[GRAPH COMPLETE]</code>；若被批准的不是末节点，<code>phase</code> 会是 <code>executing</code>，下游节点立刻被派发。</p><p><code>applied</code> 回答的是「这次决策真的起作用了吗」：对已经解决的节点重复批准不会报错，但 <code>applied</code> 会是 <code>false</code>——它标记的是一次空操作。</p><p>若定稿不合格，改用拒绝，并把理由说清楚：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_approve({ graph_id: &quot;review-pipeline-gated&quot;, node_id: &quot;finalize&quot;, action: &quot;reject&quot;,</span></span>
<span class="line"><span>                reason: &quot;结论缺少风险评估，补上再交&quot; })</span></span></code></pre></div><p>拒绝走哪条路由，取决于这个节点有没有循环组：属于循环组的节点回到 <code>ready</code> 重跑，<code>reason</code> 会被拼进它的重跑提示词；不属于任何循环组的节点没有回头路，直接升级为 <code>escalate</code>。本例的 <code>finalize</code> 没有循环组，所以「打回重做」需要下一节的循环组支撑。</p><h2 id="第-5-步-给「打回重做」加硬上限" tabindex="-1">第 5 步：给「打回重做」加硬上限 <a class="header-anchor" href="#第-5-步-给「打回重做」加硬上限" aria-label="Permalink to &quot;第 5 步：给「打回重做」加硬上限&quot;">​</a></h2><p>现在让 <code>reviewer</code> 能打回 <code>coder</code> 重做，同时保证它不能无限打回。循环组要在 <code>graph_run</code> 之前声明好，所以这里新建第二张图：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>再建一张图 review-loop-lab，只放两个节点：coder 与 reviewer。</span></span>
<span class="line"><span>coder → reviewer 是 always 边；reviewer 发现问题时调用 signal 工具发 revise_needed，</span></span>
<span class="line"><span>把问题清单放进 payload。再声明一个循环组 review-loop，成员是这两个节点，</span></span>
<span class="line"><span>max_traversals 设 3。reviewer 的提示词里写明：有问题发 revise_needed，通过则发 answer。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_create({ name: &quot;review-loop-lab&quot; })</span></span>
<span class="line"><span>graph_add_node({ graph_id: &quot;review-loop-lab&quot;, id: &quot;coder&quot;,</span></span>
<span class="line"><span>                 agent: &quot;code-reviewer--coder&quot;, prompt: &quot;实现改动并输出补丁&quot; })</span></span>
<span class="line"><span>graph_add_node({ graph_id: &quot;review-loop-lab&quot;, id: &quot;reviewer&quot;,</span></span>
<span class="line"><span>                 agent: &quot;code-reviewer--reviewer&quot;,</span></span>
<span class="line"><span>                 prompt: &quot;有问题发 revise_needed（清单放 payload），通过则发 answer&quot; })</span></span>
<span class="line"><span>graph_add_edge({ graph_id: &quot;review-loop-lab&quot;, from: &quot;coder&quot;, to: &quot;reviewer&quot; })</span></span>
<span class="line"><span>graph_add_edge({ graph_id: &quot;review-loop-lab&quot;, from: &quot;reviewer&quot;, to: &quot;coder&quot;,</span></span>
<span class="line"><span>                 type: &quot;on_signal&quot;, signal_filter: [&quot;revise_needed&quot;] })</span></span>
<span class="line"><span>graph_add_loop({ graph_id: &quot;review-loop-lab&quot;, id: &quot;review-loop&quot;,</span></span>
<span class="line"><span>                 nodes: [&quot;coder&quot;, &quot;reviewer&quot;], max_traversals: 3 })</span></span>
<span class="line"><span>graph_run({ graph_id: &quot;review-loop-lab&quot; })</span></span></code></pre></div><p>回边必须是 <code>on_signal</code> 且 <code>signal_filter</code> 里含 <code>revise_needed</code>——只有这种边被引擎认作「修订回边」，<code>always</code> 边是前进数据流，不参与回环。还要注意顺序：<code>graph_add_loop</code> 要求成员节点真的构成一个有向环，回边还没加时它会直接报错，所以先加回边、再声明循环组。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出）：</span></span>
<span class="line"><span>{ &quot;loop_id&quot;: &quot;review-loop&quot;, &quot;graph_id&quot;: &quot;review-loop-lab&quot;,</span></span>
<span class="line"><span>  &quot;nodes&quot;: [&quot;coder&quot;, &quot;reviewer&quot;], &quot;max_traversals&quot;: 3 }</span></span></code></pre></div><p><strong><code>max_traversals</code> 是硬性遍历上限</strong>，含义只有一个：这个循环组最多接受几次打回，<code>max_traversals: 3</code> 就是最多三轮重做，取值必须是 ≥ 1 的整数。它不是一个条件表达式，也没有配套的条件配置块——它就是上限本身。</p><p>运行时它这样记账：<code>reviewer</code> 每发出一次 <code>revise_needed</code>，引擎就把该循环组的遍历计数 +1，并把 <code>coder</code> 重新置为 <code>ready</code> 再跑一遍（重跑提示词里会带上这一轮的修订意见）；当计数已达上限、又收到一次 <code>revise_needed</code> 时，节点不再重跑，直接以 <code>max_traversals exhausted</code> 收尾，并带上 <code>{ reason, unresolved, traversals }</code> 的结构化说明。无论评审多挑剔，这条流水线最多重跑三轮就会停下来交给人处理。</p><p>另有一条与次数无关的早退：如果连续两次打回的 payload 完全相同，说明重跑没有带来任何变化，引擎判定为 <code>stuck</code> 并在消耗次数之前收尾。</p><p>跑起来之后，可以在状态里看到循环进度：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>graph_status({ graph_id: &quot;review-loop-lab&quot;, include_loops: true })</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应看到（示例输出）：</span></span>
<span class="line"><span>Graph &quot;review-loop-lab&quot;  [phase: executing]</span></span>
<span class="line"><span>  NODE                  STATUS      AGENT</span></span>
<span class="line"><span>  coder                 completed   code-reviewer--coder</span></span>
<span class="line"><span>  reviewer              running     code-reviewer--reviewer</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Loops:</span></span>
<span class="line"><span>    review-loop  [1/3]  nodes: coder, reviewer</span></span></code></pre></div><p><code>[1/3]</code> 就是「已重入 1 次 / 上限 3 次」。</p><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><ol><li><strong>只写了 <code>needs_approval: true</code>，却没让节点发 <code>need_approval</code> 信号。</strong> 门不会自己关上：图会一路跑到 <code>complete</code>，你永远等不到 <code>[GRAPH BLOCKED]</code>。</li><li><strong>给审批门节点的出边写了 <code>type: &quot;always&quot;</code>。</strong> 结构校验会拒绝这种图：审批节点的出边只能是 <code>on_signal</code> 或 <code>on_condition</code>，因为审批结果本身就是一次信号，<code>always</code> 会绕过它。</li><li><strong>先声明循环组、后加回边。</strong> <code>graph_add_loop</code> 要求成员节点真的构成有向环，顺序反了会报错。</li><li><strong><code>max_traversals: 0</code>。</strong> 取值必须 ≥ 1；想「不循环」就不要声明循环组。</li><li><strong>在 <code>graph_approve</code> 之前取消了节点或整张图。</strong> 决策会退化成空操作（<code>applied: false</code>），节点不会因为批准而复活。</li></ol><h2 id="你现在拥有什么" tabindex="-1">你现在拥有什么 <a class="header-anchor" href="#你现在拥有什么" aria-label="Permalink to &quot;你现在拥有什么&quot;">​</a></h2><ul><li>一张带人工审批门的流水线：<code>[GRAPH BLOCKED]</code> → <code>pending_approvals</code> → <code>graph_approve</code>（批准或带理由打回）；</li><li>一条有硬上限的评审回环：<code>reviewer</code> 发 <code>revise_needed</code> 打回 <code>coder</code>，最多 <code>max_traversals</code> 轮；</li><li>三种「图停下来了」的判据：有人等着批（<code>blocked</code>）、次数用完（<code>max_traversals exhausted</code>）、原地打转（<code>stuck</code>）。</li></ul><p>下一章 <a href="/rolebox-docs/02-Guide/tutorial/07-memory.html">07 让代理记住你</a>：把这一路上定下来的决策写进记忆库，让下一个会话的代理自动记得。</p>`,50)])])}const h=a(p,[["render",t]]);export{g as __pageData,h as default};
